import{z as s,x as B,o as l,c as d,q as o,j as i,D as e,d as E,s as n,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"NF4 与分位量化","description":"","frontmatter":{"title":"NF4 与分位量化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/nf4-quantile.md","filePath":"llm/nf4-quantile.md","lastUpdated":1791413859000}'),p={name:"llm/nf4-quantile.md"};function N(m,a,D,F,T,u){const r=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=o('<h1 id="nf4-与分位量化" tabindex="-1">NF4 与分位量化 <a class="header-anchor" href="#nf4-与分位量化" aria-label="Permalink to &quot;NF4 与分位量化&quot;">​</a></h1><div class="epigraph"><p>正态权重的质量堆在零附近。把 16 个 4-bit 码字按标准正态的分位切开，每个箱子概率质量接近相等——这就是 NF4，不是又一种 INT4。</p><footer>—— Dettmers 等，QLoRA；分位量化作为非均匀码本的实例</footer></div><p><a href="/llm/mixed-precision-search">混精</a> 在均匀格子上分配 bit。本课换码本几何： <strong>分位量化 / NF4</strong>。<a href="/llm/uniform-nonuniform-quant">均匀 vs 非均匀</a> 已立对立；<a href="/llm/qlora">QLoRA</a> 主课写过训练期存储。缺口是课序里把 NF4 讲成量化基础的一环：它优化的是<strong>冻结权重的存储</strong>，查表反量化后仍在 16-bit 里算，和 <a href="/llm/gptq">GPTQ</a> 的 INT 网格不是同一检查点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>均匀 INT4 在高斯中心浪费间距、在尾部过粗。按 \\(\\mathcal{N}(0,1)\\) 的分位取 16 个水平，使 \\(P(c_i \\lt z \\lt c_{i+1})\\) 近似相等，信息论上匹配「权重先标准化再量化」的假设。块内标准化（减均或只除标准差）把各块拉到同一张码本上，码本可固定、不学。</p>',5)),(l(),i(A,null,{default:e(()=>[n(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIST%5B%22%E6%A0%87%E5%87%86%E5%8C%96%E5%90%8E%E6%9D%83%E9%87%8D%20%E2%89%88%20%E9%92%9F%E5%BD%A2%E5%88%86%E5%B8%83%22%5D%20--%3E%20U%5B%22%E5%9D%87%E5%8C%80%20INT4%3A%2016%20%E6%A0%BC%E7%AD%89%E5%AE%BD%22%5D%0A%20%20U%20--%3E%20W1%5B%22%E4%B8%AD%E5%BF%83%E6%A0%BC%E8%BF%87%E5%AF%86%20%E5%A4%9A%E6%95%B0%E6%A0%BC%E5%AD%90%E6%B5%AA%E8%B4%B9%22%5D%0A%20%20U%20--%3E%20W2%5B%22%E5%B0%BE%E9%83%A8%E6%A0%BC%E8%BF%87%E7%96%8F%20%E7%A6%BB%E7%BE%A4%E8%A2%AB%E5%A4%B9%E5%B9%B3%22%5D%0A%20%20DIST%20--%3E%20NF%5B%22NF4%3A%2016%20%E6%A0%BC%E7%AD%89%E6%A6%82%E7%8E%87%22%5D%0A%20%20NF%20--%3E%20G1%5B%22%E6%AF%8F%E6%A0%BC%E6%8E%A5%E4%BD%8F%E7%BA%A6%201%2F16%20%E7%9A%84%E6%9D%83%E9%87%8D%22%5D%0A%20%20NF%20--%3E%20G2%5B%22%E4%B8%AD%E5%BF%83%E6%A0%BC%E7%AA%84%20%E5%B0%BE%E6%A0%BC%E5%AE%BD%20%E5%90%84%E5%BE%97%E5%85%B6%E6%89%80%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[t("span",{class:"marginnote"},"分位切法可以类比按人数分档：不按固定身高刻度切，而是让每一档的人数一样多。权重大多挤在 0 附近，NF4 就在 0 附近切细格子、在稀疏的尾部用宽格子——16 个码字个个都「有人用」，没有空转的档位。")],-1)),a[4]||(a[4]=t("p",null,[E("没有 INT4 Tensor Core 时，NF4 的墙钟收益主要是显存与加载带宽（若核真按 4-bit 存）。反量化成 FP16 再乘，算力墙场景不加速。问题是认清："),t("strong",null,"NF4 是存储码本，GPTQ 是整数网格加补偿"),E("，不能互换文件。")],-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"NF4 名字强调 NormalFloat、4-bit。还有 FP4 等格式，语义不同。本课 NF4 特指 QLoRA 那张固定分位表。")],-1)),a[6]||(a[6]=t("h2",{id:"方法",tabindex:"-1"},[E("方法 "),t("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[7]||(a[7]=t("p",null,"块长（如 64）标准化 → 映到 16 个分位水平 → 存 4-bit 下标 + 块尺度。双重量化再压尺度，见 QLoRA 主课。推理若继续当 QLoRA 基座，反量化约定必须一致。若目标是 INT4 GEMM 部署，应走 GPTQ/AWQ，而不是把 NF4 张量「当成 INT4」送进整数核。",-1)),(l(),i(A,null,{default:e(()=>[n(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%E5%9D%97%22%5D%20--%3E%20N%5B%22%E6%A0%87%E5%87%86%E5%8C%96%22%5D%0A%20%20N%20--%3E%20Q%5B%22%E5%88%86%E4%BD%8D%E7%A0%81%E6%9C%AC%2016%20%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20Q%20--%3E%20ST%5B%224-bit%20%E4%B8%8B%E6%A0%87%20%2B%20%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20ST%20--%3E%20DQ%5B%22%E5%8F%8D%E9%87%8F%E5%8C%96%E5%88%B0%20FP16%22%5D%0A%20%20DQ%20--%3E%20GEMM%5B%2216-bit%20%E8%AE%A1%E7%AE%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p>与均匀分组：同样是 per-group 尺度，差别在组内码字是否等差。直方图更峰、更高斯，NF4 越占优；多峰、有硬饱和，分位表可能错位。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>等概率箱子 ≈ 最小化对给定分布的均匀码字浪费。假设错了（权重并非正态、块内离群未标准化掉），分位切在错误密度上，比均匀还差。块标准化是假设的一部分：块太大，块内方差不齐；块太小，尺度元数据反弹。</p><p><span class="marginnote">常见误区：以为 NF4 的 16 个水平是「每个模型各自算」的。其实 QLoRA 那张码本对标准正态是固定的、所有模型共用，模型间变的只是每块的尺度——所以换模型不需要重训量化器，分位表的校准代价近乎为零。</span></p><p>训练时冻结 \\(W_0\\) 用 NF4 存、计算用 16-bit，LoRA 梯度不被 4-bit 算术淹没。部署若坚持这条路径，没有「INT4 加速」，只有容量。</p><p><span class="marginnote">省了多少，代个数字：7B 参数的权重，FP16 约 14 GB；NF4 按每元素 4 bit 多一点（块尺度摊薄）算约 3.7 GB——同一张 24 GB 卡上，前者放不下、后者还留得出激活与 LoRA 参数的空间，这就是 QLoRA「单卡微调」故事的算术底座。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 AutoGPTQ 的 INT4 与 bitsandbytes NF4 混加载。不要在对比加速器时把 NF4 算进「INT4 核吞吐」。不要对激活用 NF4——激活不是静态正态权重。下一课 FP8：硬件原生的另一种非均匀（指数格子），面向计算而非存储码本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NF4：标准正态分位码本 + 块标准化，QLoRA 的存储格式。</li><li>计算仍在较高精度；与 GPTQ 均匀 INT 网格不互换。</li><li>假设权重近似高斯；假设失败时不如均匀。</li><li>无对应加载核则只省容量。</li><li>出处：Dettmers 等 QLoRA；分位量化与非均匀课的接口。</li></ul>',10))])}const h=s(p,[["render",N]]);export{b as __pageData,h as default};
